    "Luminetis home": "La maison Luminétis",
    "Luminetis is a small studio of senior engineers, with people in Luxembourg and Kosovo. Today that is two senior software engineers with a combined decade-plus of commercial experience, including work with UK-based companies. When a project needs more, we bring in senior people we have worked with before: software, data and AI engineers at the same level, never a junior team learning on your budget.": "Luminetis est un petit studio d'ingénieurs seniors, avec des collaborateurs au Luxembourg et au Kosovo. Il s’agit aujourd’hui de deux ingénieurs logiciels senior cumulant plus d’une décennie d’expérience commerciale, notamment auprès d’entreprises basées au Royaume-Uni. Lorsqu'un projet a besoin de plus, nous faisons appel à des personnes expérimentées avec lesquelles nous avons déjà travaillé : des ingénieurs logiciels, données et IA du même niveau, jamais une équipe junior apprenant sur votre budget.",
