    "month 12": "mois 12",
    "Monthly plans end with notice. Your site, code, domain and data stay yours, and we hand over anything we hold before the plan closes.": "Les forfaits mensuels se terminent avec préavis. Votre site, votre code, votre domaine et vos données restent les vôtres, et nous remettons tout ce que nous détenons avant la clôture du plan.",
    "Monthly reconciliation runs unattended and mismatches surface the same day they happen.": "Le rapprochement mensuel s'effectue sans surveillance et les disparités apparaissent le jour même où elles se produisent.",
    "Most of our work is under NDA, so we describe it by sector, country, scale and problem rather than by client name. Clients in Luxembourg, Kosovo, the United Kingdom and the United States. References are available on request.": "La plupart de notre travail est sous NDA, nous le décrivons donc par secteur, pays, échelle et problème plutôt que par nom de client. Clients au Luxembourg, au Kosovo, au Royaume-Uni et aux Etats-Unis. Les références sont disponibles sur demande.",
    "Most small businesses do not want a website. They want the phone to ring. That happens in the map result above the search results, and it only happens if the listing exists, is verified, and is complete.": "La plupart des petites entreprises ne veulent pas de site Web. Ils veulent que le téléphone sonne. Cela se produit dans le résultat de la carte au-dessus des résultats de recherche, et cela ne se produit que si la liste existe, est vérifiée et est complète.",
    "Moved filtering to a pre-built facet index, deferred image decoding, and cut third-party scripts from eleven to three.": "Déplacement du filtrage vers un index de facettes prédéfini, décodage d'image différé et réduction des scripts tiers de onze à trois.",
