    "Name": "Nom",
    "Native and cross-platform apps, internal tools, dashboards, integrations and API design, usually where a spreadsheet stopped being enough.": "Applications natives et multiplateformes, outils internes, tableaux de bord, intégrations et conception d'API, généralement là où une feuille de calcul ne suffisait plus.",
