    "natural wine luxembourg": "vin naturel luxembourg",
    "Nearer the centre is what we do most weeks. Further out is work we have done and would take again. Hover any of them.": "Plus près du centre, c'est ce que nous faisons la plupart des semaines. Plus loin, il y a le travail que nous avons fait et que nous reprendrons. Survolez l'un d'entre eux.",
