    "Not a complete list, and not the limit. If your problem is not on it, ask. We will tell you plainly whether it is ours to take or someone else&apos;s.": "Pas une liste complète, ni une limite. Si votre problème ne vient pas de là, demandez. Nous vous dirons clairement si c'est à nous ou à quelqu'un d'autre de le prendre.",
