    "On-site work in Luxembourg and Kosovo, remote work with the US, the UK and the rest of Europe. We shift our hours to overlap with yours.": "Travail sur site au Luxembourg et au Kosovo, travail à distance avec les États-Unis, le Royaume-Uni et le reste de l'Europe. Nous décalons nos horaires pour qu'ils chevauchent les vôtres.",
    "One booking flow for three venues": "Un flux de réservation pour trois sites",
    "One booking service with per-venue capacity rules, confirmation email, and a staff view that works on a phone behind the bar.": "Un service de réservation avec des règles de capacité par site, un e-mail de confirmation et une vue du personnel qui fonctionne sur un téléphone derrière le bar.",
    "One build fee, then the plan that keeps you found": "Un seul frais de construction, puis le plan qui vous permet de rester trouvé",
    "One build fee. Then the plan that keeps you found.": "Un frais de construction. Ensuite, le plan qui vous maintient trouvé.",
    "One conversation about what the business needs, then a written scope with a fixed price. If a cheaper package fits, we say so.": "Une conversation sur les besoins de l'entreprise, puis un cahier des charges écrit avec un prix fixe. Si un forfait moins cher vous convient, nous le disons.",
    "One of us is a PhD candidate in quantum computing. If quantum-backed services become production-ready, clients on an active care plan get their existing services migrated with no additional build fee. Running costs are separate and stated in advance.": "L’un de nous est doctorant en informatique quantique. Si les services quantiques deviennent prêts pour la production, les clients bénéficiant d’un plan de soins actifs voient migrer leurs services existants sans frais de création supplémentaires. Les frais de fonctionnement sont distincts et déclarés à l'avance.",
    "One of us is a PhD candidate in quantum computing. That is the reason this studio exists and where the name comes from. Light is how quantum machines will carry information, and it is how people find you today.": "L’un de nous est doctorant en informatique quantique. C'est la raison pour laquelle ce studio existe et d'où vient son nom. La lumière est la manière dont les machines quantiques transportent l’information, et c’est ainsi que les gens vous trouvent aujourd’hui.",
    "One team, start to long after launch": "Une équipe, commence bien après le lancement",
