    "Supplier price lists arrived as HTML pages and PDFs, and every layout change silently broke the import.": "Les listes de prix des fournisseurs arrivaient sous forme de pages HTML et de fichiers PDF, et chaque changement de mise en page interrompait silencieusement l'importation.",
