    "Each venue took bookings differently: phone, a form, and a third-party widget. Double-bookings were routine.": "Jeder Veranstaltungsort nahm Buchungen anders entgegen: per Telefon, über ein Formular und über ein Drittanbieter-Widget. Doppelbuchungen waren an der Tagesordnung.",
