    "Essential is usually two to three weeks from receiving your material. Growth is four to six. Custom is quoted with a schedule attached.": "Unverzichtbar sind in der Regel zwei bis drei Wochen nach Erhalt Ihres Materials. Das Wachstum beträgt vier bis sechs. Kundenspezifische Angebote werden mit beigefügtem Zeitplan angeboten.",
