    "Extraction with per-supplier adapters, schema validation, and an alert when a field disappears rather than a silent null.": "Extraktion mit lieferantenspezifischen Adaptern, Schemavalidierung und eine Warnung, wenn ein Feld verschwindet, statt einer stillen Null.",
