    "Filtering became instant on mid-range phones and the collection pages passed Core Web Vitals.": "Die Filterung erfolgte auf Mittelklasse-Telefonen sofort und die Sammlungsseiten erfüllten die Anforderungen von Core Web Vitals.",
    "Finance and KYC": "Finanzen und KYC",
    "First reply": "Erste Antwort",
    "First reply within 8 business hours. Site-down incidents on a care plan acknowledged within 2 hours during business hours, and within 12 hours outside them.": "Erste Antwort innerhalb von 8 Geschäftsstunden. Vorfälle mit Standortausfall im Rahmen eines Pflegeplans werden innerhalb von 2 Stunden während der Geschäftszeiten und innerhalb von 12 Stunden außerhalb dieser Stunden bestätigt.",
    "first-load JS": "JS zum ersten Mal laden",
