    "followers, from zero": "Follower, von Null",
    "For 90 days after launch, anything that does not work as agreed gets fixed at no cost. On an active care plan, that window does not close.": "90 Tage nach der Einführung wird alles, was nicht wie vereinbart funktioniert, kostenlos behoben. Bei einem aktiven Pflegeplan wird dieses Fenster nicht geschlossen.",
    "For a business that needs the site to bring in work.": "Für ein Unternehmen, das die Website benötigt, um Arbeit zu generieren.",
    "For a business that needs to exist properly online and be found.": "Für ein Unternehmen, das online existieren und gefunden werden muss.",
    "For larger builds we add senior software, data and AI engineers we have worked with before. Same seniority, same accountability, and you are told who they are before they start.": "Bei größeren Builds ziehen wir erfahrene Software-, Daten- und KI-Ingenieure hinzu, mit denen wir bereits zusammengearbeitet haben. Gleiches Dienstalter, gleiche Verantwortlichkeit, und man sagt Ihnen, wer sie sind, bevor sie anfangen.",
    "For work where the requirements are genuinely specific.": "Für Arbeiten, bei denen die Anforderungen wirklich spezifisch sind.",
