    "Google Business Profile created, claimed and verified, Maps presence, local search, Search Console and indexing, sitemap and structured data, reviews answered.": "Google-Unternehmensprofil erstellt, beansprucht und verifiziert, Maps-Präsenz, lokale Suche, Search Console und Indexierung, Sitemap und strukturierte Daten, Bewertungen beantwortet.",
