    "Handlers spent much of the day searching PDFs for policy wording that decided a claim.": "Die Sachbearbeiter verbrachten einen Großteil des Tages damit, PDFs nach Richtlinientexten zu durchsuchen, die über einen Anspruch entschieden.",
