    "How we work and what we are accountable for": "Wie wir arbeiten und wofür wir verantwortlich sind",
    "I agree that Luminetis may store what I send in order to reply to me.": "Ich bin damit einverstanden, dass Luminetis das, was ich sende, speichert, um mir zu antworten.",
    "Identity, design systems, UI design, editorial content and product copy, enough design to look like a business people trust.": "Identität, Designsysteme, UI-Design, redaktioneller Inhalt und Produkttext – genug Design, um wie ein Unternehmen auszusehen, dem die Leute vertrauen.",
    "If something goes wrong": "Wenn etwas schief geht",
    "If we ever break one of these, tell us and we will make it right.": "Sollten wir jemals eines davon kaputt machen, sagen Sie es uns und wir werden es wieder in Ordnung bringen.",
    "If we underestimated, that is ours to absorb. Scope changes are quoted and approved before any work starts.": "Wenn wir unterschätzt haben, müssen wir das auffangen. Umfangsänderungen werden vor Beginn der Arbeiten angeboten und genehmigt.",
    "If we underestimated, that is ours to absorb. Scope changes are quoted and approved in writing before any work starts.": "Wenn wir unterschätzt haben, müssen wir das auffangen. Umfangsänderungen werden vor Beginn der Arbeiten schriftlich angeboten und genehmigt.",
    "If your problem looks like one of these, we have solved it before.": "Wenn Ihr Problem so aussieht, haben wir es bereits gelöst.",
    "Illustrative figures showing the shape of a first year, not a client result. We do not publish numbers we did not measure.": "Anschauliche Zahlen, die die Form eines ersten Jahres zeigen, kein Kundenergebnis. Wir veröffentlichen keine Zahlen, die wir nicht gemessen haben.",
    "In every package": "In jedem Paket",
    "In Luxembourg and Kosovo, yes, including network and server work. Elsewhere the work is remote.": "In Luxemburg und im Kosovo ja, inklusive Netzwerk- und Serverarbeiten. Anderswo ist die Arbeit abgelegen.",
    "Including when a cheaper package is the right one, and when the thing you asked for will not get you what you want.": "Auch wenn ein günstigeres Paket das Richtige ist und wenn das, wonach Sie gefragt haben, Ihnen nicht das bringt, was Sie wollen.",
    "Indexing, profile verification, analytics and a handover document. Accounts in your name from the start.": "Indizierung, Profilverifizierung, Analyse und ein Übergabedokument. Konten von Anfang an auf Ihren Namen.",
