    "luminetis": "Luminetis",
    "Luminetis home": "Luminetis-Heim",
    "Luminetis is a small studio of senior engineers, with people in Luxembourg and Kosovo. Today that is two senior software engineers with a combined decade-plus of commercial experience, including work with UK-based companies. When a project needs more, we bring in senior people we have worked with before: software, data and AI engineers at the same level, never a junior team learning on your budget.": "Luminetis ist ein kleines Studio leitender Ingenieure mit Mitarbeitern in Luxemburg und im Kosovo. Heute sind das zwei leitende Software-Ingenieure mit zusammen mehr als einem Jahrzehnt kaufmännischer Erfahrung, unter anderem durch die Arbeit bei in Großbritannien ansässigen Unternehmen. Wenn ein Projekt mehr erfordert, ziehen wir erfahrene Mitarbeiter hinzu, mit denen wir bereits zusammengearbeitet haben: Software-, Daten- und KI-Ingenieure auf dem gleichen Niveau, niemals ein Nachwuchsteam, das mit Ihrem Budget lernt.",
    "luminetis-locale": "Luminetis-Gebietsschema",
