    "Made in small runs": "Hergestellt in kleinen Auflagen",
    "Magazine": "Magazin",
    "Mapped every URL, wrote the redirect set from the old sitemap, and verified it against server logs after cutover.": "Jede URL zugeordnet, den Umleitungssatz aus der alten Sitemap geschrieben und ihn nach der Umstellung anhand der Serverprotokolle überprüft.",
    "Maps listing maintained": "Die Kartenliste wird beibehalten",
    "Marketing sites": "Marketingseiten",
    "Marketing sites, custom builds, Shopify and BigCommerce, headless commerce, migrations without losing URLs, and performance work on sites we did not build.": "Marketing-Sites, benutzerdefinierte Builds, Shopify und BigCommerce, Headless Commerce, Migrationen ohne URL-Verlust und Performance-Arbeit an Sites, die wir nicht erstellt haben.",
