    "Mobile apps": "Mobile Apps",
    "Monitor reviews and draft responses you can send as they are.": "Überwachen Sie Bewertungen und Antwortentwürfe, die Sie unverändert senden können.",
    "Monitoring": "Überwachung",
    "month 1": "Monat 1",
    "month 12": "Monat 12",
    "Monthly plans end with notice. Your site, code, domain and data stay yours, and we hand over anything we hold before the plan closes.": "Monatspläne enden mit Kündigung. Ihre Website, Ihr Code, Ihre Domain und Ihre Daten bleiben Ihr Eigentum und wir übergeben alles, was wir besitzen, bevor der Plan endet.",
    "Monthly reconciliation runs unattended and mismatches surface the same day they happen.": "Der monatliche Abgleich läuft unbeaufsichtigt und Abweichungen treten noch am selben Tag auf, an dem sie auftreten.",
    "Most of our work is under NDA, so we describe it by sector, country, scale and problem rather than by client name. Clients in Luxembourg, Kosovo, the United Kingdom and the United States. References are available on request.": "Die meisten unserer Arbeiten unterliegen der Geheimhaltungsvereinbarung (NDA), daher beschreiben wir sie nach Sektor, Land, Umfang und Problem und nicht nach Kundennamen. Kunden in Luxemburg, Kosovo, dem Vereinigten Königreich und den Vereinigten Staaten. Referenzen sind auf Anfrage erhältlich.",
    "Most small businesses do not want a website. They want the phone to ring. That happens in the map result above the search results, and it only happens if the listing exists, is verified, and is complete.": "Die meisten kleinen Unternehmen möchten keine Website. Sie wollen, dass das Telefon klingelt. Dies geschieht im Kartenergebnis über den Suchergebnissen und nur dann, wenn der Eintrag vorhanden, verifiziert und vollständig ist.",
    "Moved filtering to a pre-built facet index, deferred image decoding, and cut third-party scripts from eleven to three.": "Die Filterung wurde auf einen vorgefertigten Facettenindex verschoben, die Bilddekodierung verzögert und die Skripte von Drittanbietern wurden von elf auf drei reduziert.",
    "ms": "Frau",
    "name": "Namen",
    "Name": "Name",
    "Native and cross-platform apps, internal tools, dashboards, integrations and API design, usually where a spreadsheet stopped being enough.": "Native und plattformübergreifende Apps, interne Tools, Dashboards, Integrationen und API-Design – oft dort, wo eine Tabellenkalkulation nicht mehr ausreicht.",
    "Native mobile apps": "Native mobile Apps",
    "natural wine luxembourg": "Naturwein Luxemburg",
    "Nearer the centre is what we do most weeks. Further out is work we have done and would take again. Hover any of them.": "Näher am Zentrum ist das, was wir in den meisten Wochen tun. Weiter draußen finden wir Arbeiten, die wir bereits erledigt haben und die wir wieder übernehmen würden. Bewegen Sie den Mauszeiger über einen von ihnen.",
    "Network and server work, on site in Luxembourg or Kosovo": "Netzwerk- und Serverarbeiten, vor Ort in Luxemburg oder im Kosovo",
