    "No lock-in": "Kein Lock-in",
    "No lock-in, leave whenever you want and take everything": "Keine Bindung, gehen Sie wann immer Sie wollen und nehmen Sie alles mit",
    "No.": "Nein.",
    "non-scaling-stroke": "nicht schuppender Strich",
    "none": "keine",
    "Not a complete list, and not the limit. If your problem is not on it, ask. We will tell you plainly whether it is ours to take or someone else&apos;s.": "Keine vollständige Liste und nicht die Grenze. Wenn Ihr Problem nicht darin liegt, fragen Sie nach. Wir sagen Ihnen klar und deutlich, ob es uns gehört oder jemand anderem.",
    "Number pending": "Nummer steht noch aus",
    "of": "von",
    "On-page SEO": "On-Page-SEO",
    "On-site IT": "IT vor Ort",
    "On-site network design and setup": "Netzwerkdesign und -einrichtung vor Ort",
    "On-site network work": "Netzwerkarbeit vor Ort",
    "On-site work in Luxembourg and Kosovo, remote work with the US, the UK and the rest of Europe. We shift our hours to overlap with yours.": "Vor-Ort-Arbeit in Luxemburg und im Kosovo, Remote-Arbeit in den USA, Großbritannien und dem Rest Europas. Wir verschieben unsere Arbeitszeiten so, dass sie sich mit Ihren überschneiden.",
    "One booking flow for three venues": "Ein Buchungsablauf für drei Veranstaltungsorte",
    "One booking service with per-venue capacity rules, confirmation email, and a staff view that works on a phone behind the bar.": "Ein Buchungsservice mit Kapazitätsregeln pro Veranstaltungsort, Bestätigungs-E-Mail und einer Mitarbeiteransicht, die über ein Telefon hinter der Bar funktioniert.",
    "One build fee, then the plan that keeps you found": "Eine Baugebühr, dann der Plan, mit dem Sie gefunden werden",
    "One build fee. Then the plan that keeps you found.": "Eine Baugebühr. Dann der Plan, mit dem Sie gefunden werden.",
    "One conversation about what the business needs, then a written scope with a fixed price. If a cheaper package fits, we say so.": "Ein Gespräch darüber, was das Unternehmen braucht, dann ein schriftlicher Leistungsumfang mit Festpreis. Wenn ein günstigeres Paket passt, sagen wir es.",
    "One of us is a PhD candidate in quantum computing. If quantum-backed services become production-ready, clients on an active care plan get their existing services migrated with no additional build fee. Running costs are separate and stated in advance.": "Einer von uns ist Doktorand im Quantencomputing. Wenn quantengestützte Dienste produktionsreif werden, können Kunden mit einem aktiven Pflegeplan ihre bestehenden Dienste ohne zusätzliche Build-Gebühr migrieren. Die laufenden Kosten werden separat berechnet und im Voraus angegeben.",
    "One of us is a PhD candidate in quantum computing. That is the reason this studio exists and where the name comes from. Light is how quantum machines will carry information, and it is how people find you today.": "Einer von uns ist Doktorand im Quantencomputing. Das ist der Grund, warum dieses Studio existiert und woher der Name stammt. Licht ist die Art und Weise, wie Quantenmaschinen Informationen transportieren, und es ist die Art und Weise, wie Menschen Sie heute finden.",
    "One team, start to long after launch": "Ein Team, starten Sie lange nach dem Start",
    "One warehouse as the source of truth, typed transforms, and a dashboard with the figures each stakeholder actually asks for.": "Ein Lager als Quelle der Wahrheit, typisierte Transformationen und ein Dashboard mit den Zahlen, nach denen jeder Stakeholder tatsächlich fragt.",
    "one-off": "einmalig",
    "Open now": "Jetzt geöffnet",
    "Open today · 08:00 to 18:00": "Heute geöffnet · 08:00 bis 18:00 Uhr",
    "Open until 01:00 · Luxembourg-Gare": "Geöffnet bis 01:00 · Luxembourg-Gare",
    "Orange, skin contact": "Orange, Hautkontakt",
    "Orbit Agents": "Orbit-Agenten",
    "Organic sessions held through the migration with no ranking cliff in the following weeks.": "Organische Sitzungen wurden während der Migration abgehalten, ohne dass es in den folgenden Wochen zu Rangabfällen kam.",
    "Outcome": "Ergebnis",
    "outline": "Umriss",
