    "Packages": "Pakete",
    "page": "Seite",
    "Page-speed work on existing sites": "Pagespeed-Arbeit auf bestehenden Websites",
    "Paid and social where it earns its budget, with the tracking set up properly so you can tell whether it did.": "Bezahlt und sozial, wo das Budget verdient wird, mit richtig eingerichteter Nachverfolgung, damit Sie erkennen können, ob es das getan hat.",
    "Paint that looks better than the day it left the factory.": "Lack, der besser aussieht als am Tag, an dem er das Werk verlassen hat.",
    "Patching, monitoring, backups, edits, and a monthly report in plain language. A named person answers your email.": "Patching, Überwachung, Backups, Bearbeitungen und ein monatlicher Bericht im Klartext. Eine namentlich genannte Person beantwortet Ihre E-Mail.",
