    "Settlement reconciliation was done by hand from block explorers, taking two days per month and disagreeing with the ledger.": "Der Abrechnungsabgleich wurde von Blockexplorern manuell durchgeführt, was zwei Tage pro Monat in Anspruch nahm und nicht mit dem Hauptbuch übereinstimmte.",
