    "Sites that load in about a second on a phone on mobile data, and web applications that hold up when the business grows into them.": "Websites, die über mobile Daten in etwa einer Sekunde auf einem Telefon geladen werden, und Webanwendungen, die auch dann bestehen bleiben, wenn das Unternehmen wächst.",
