    "Technical work first, because content ranks only if the site can be crawled and read quickly. Then the writing.": "Technische Arbeit steht an erster Stelle, da Inhalte nur dann ranken, wenn die Website schnell gecrawlt und gelesen werden kann. Dann das Schreiben.",
