    "Tell us what you sell and where you are": "Sagen Sie uns, was Sie verkaufen und wo Sie sind",
    "Tell us what you sell and where you are.": "Sagen Sie uns, was Sie verkaufen und wo Sie sind.",
    "Ten years of commercial work. Some of it we had to go back through invoices to remember.": "Zehn Jahre kaufmännische Tätigkeit. Einiges davon mussten wir noch einmal in Rechnungen durchsehen, um uns daran zu erinnern.",
