    "text": "Text",
    "Thanks. We will reply within one business day.": "Danke. Wir werden innerhalb eines Werktages antworten.",
    "The agency ranked nowhere locally and had no verified Google Business Profile for either office.": "Die Agentur hatte vor Ort keinen Rang und verfügte für keines der beiden Büros über ein verifiziertes Google-Unternehmensprofil.",
    "The build fee is one-off. Care and Found are monthly and can be cancelled with notice. The build price does not change once agreed.": "Die Baugebühr ist einmalig. Care and Found finden monatlich statt und können mit Vorankündigung gekündigt werden. Der Baupreis ändert sich nach der Vereinbarung nicht.",
    "The build is a one-off. The plan keeps the site alive and, on Found, keeps you on the map. A build requires an active Care plan; Found is optional and is what we recommend.": "Der Bau ist ein Einzelstück. Der Plan hält die Website am Leben und sorgt bei Gefunden dafür, dass Sie auf der Karte bleiben. Für einen Build ist ein aktiver Pflegeplan erforderlich. Gefunden ist optional und wird von uns empfohlen.",
    "The English version of this page governs in the event of any discrepancy with a translation.": "Im Falle von Unstimmigkeiten mit einer Übersetzung ist die englische Version dieser Seite maßgebend.",
    "The Found plan": "Der Found-Plan",
    "The last vineyards on the Moselle bend": "Die letzten Weinberge an der Moselschleife",
    "The listing was live and complete in the first week, ahead of the site launch.": "Die Auflistung war in der ersten Woche vor dem Start der Website online und vollständig.",
    "The map result · you first, competitors grey": "Das Kartenergebnis · Sie zuerst, Konkurrenten grau",
    "The monthly pack is generated rather than assembled, and the numbers reconcile.": "Das monatliche Paket wird generiert und nicht zusammengestellt, und die Zahlen werden abgeglichen.",
    "The person you talk to first is the person who writes the code, and the person who answers when something breaks a year later.": "Die Person, mit der Sie zuerst sprechen, ist die Person, die den Code schreibt, und die Person, die antwortet, wenn ein Jahr später etwas kaputt geht.",
    "The previous site was 6MB of sliders and did not open reliably on the clinic's own network.": "Die vorherige Website hatte eine Größe von 6 MB an Slidern und ließ sich im klinikeigenen Netzwerk nicht zuverlässig öffnen.",
    "The quantum commitment": "Die Quantenverpflichtung",
    "The research happens on our time. You get the result as part of your existing plan.": "Die Forschung findet in unserer Zeit statt. Das Ergebnis erhalten Sie im Rahmen Ihres bestehenden Plans.",
    "The same engineers who scoped it. You see it working early and often, on a real URL, not in a slide.": "Dieselben Ingenieure, die es geplant haben. Sie sehen, dass es früh und oft funktioniert, und zwar auf einer echten URL, nicht auf einer Folie.",
    "The same figure reads differently in Pristina and in Luxembourg City. Rather than pick one and misprice the other market, we publish both and show the list for your region. You can switch it.": "Dieselbe Zahl liest sich in Pristina und in Luxemburg-Stadt unterschiedlich. Anstatt einen Markt auszuwählen und den anderen Markt falsch zu bewerten, veröffentlichen wir beide und zeigen die Liste für Ihre Region. Sie können es wechseln.",
    "The same people scope, build, launch and maintain the work. There is no handoff to a junior team.": "Die gleichen Leute planen, bauen, starten und warten die Arbeit. Es erfolgt keine Übergabe an eine Juniorenmannschaft.",
    "The site opens in about a second on the clinic network and receptionists stopped reading the address out over the phone.": "Die Website wird im Kliniknetzwerk in etwa einer Sekunde geöffnet und die Empfangsmitarbeiter haben aufgehört, die Adresse am Telefon vorzulesen.",
    "The team": "Das Team",
    "The unglamorous half. If the office network drops out at eleven every morning, nothing else we build matters.": "Die unscheinbare Hälfte. Wenn das Büronetzwerk jeden Morgen um elf Uhr ausfällt, zählt nichts anderes, was wir aufbauen.",
    "then Care from": "dann Pflege von",
    "This one we need.": "Das hier brauchen wir.",
