    "Two bases, clients across time zones": "Zwei Stützpunkte, Kunden in allen Zeitzonen",
    "Two fields still need filling in.": "Zwei Felder müssen noch ausgefüllt werden.",
    "Two of us permanently, and a short list of senior engineers we trust when a project needs more hands. You are told who is working on your project and who to email, always.": "Zwei von uns dauerhaft und eine kurze Liste leitender Ingenieure, denen wir vertrauen, wenn ein Projekt mehr Hände benötigt. Ihnen wird jederzeit mitgeteilt, wer an Ihrem Projekt arbeitet und wem Sie eine E-Mail senden können.",
    "two offices, nine agents": "zwei Büros, neun Agenten",
