    "Up to 15 pages, or a blog, or a small catalogue": "Bis zu 15 Seiten oder ein Blog oder ein kleiner Katalog",
    "Up to 5 pages, responsive, light and dark": "Bis zu 5 Seiten, responsive, hell und dunkel",
    "Uptime is monitored and the office has not lost connectivity during working hours since installation.": "Die Betriebszeit wird überwacht und das Büro hat seit der Installation während der Arbeitszeit keine Konnektivität verloren.",
    "Uptime monitoring": "Überwachung der Betriebszeit",
    "URLs redirected": "URLs umgeleitet",
    "use client": "Client verwenden",
    "VAT treatment is pending confirmation and will be stated on every quote and invoice.": "Die Mehrwertsteuerbehandlung muss noch bestätigt werden und wird in jedem Angebot und jeder Rechnung angegeben.",
    "Verified the Google Business Profile first, completed hours, photos and categories, then built a five-page site around it.": "Zuerst das Google-Unternehmensprofil überprüft, Stunden, Fotos und Kategorien vervollständigt und dann eine fünfseitige Website darum herum erstellt.",
    "VINERA": "VINERA",
    "Vinera, your business": "Vinera, Ihr Unternehmen",
    "Warehousing": "Lagerhaltung",
    "Washer, DIN 125": "Unterlegscheibe, DIN 125",
    "Watch it happen, screen by screen.": "Beobachten Sie, wie es passiert, Bildschirm für Bildschirm.",
    "We are based in Luxembourg and Kosovo, and we work with clients in the United States, the United Kingdom and across Europe. Time zones have never been the problem: we move our hours to overlap with yours, early or late, and we say up front which hours you will get us in.": "Wir haben unseren Sitz in Luxemburg und im Kosovo und arbeiten mit Kunden in den Vereinigten Staaten, im Vereinigten Königreich und in ganz Europa zusammen. Zeitzonen waren noch nie das Problem: Wir verschieben unsere Öffnungszeiten so, dass sie sich mit Ihren überschneiden, früh oder spät, und wir sagen im Voraus, zu welchen Zeiten Sie uns bekommen.",
    "We have worked in insurance, fashion, blockchain, real estate, hospitality, medicine, reselling, e-commerce and construction. That range matters less than what it taught us: most problems are not technical, and the technical part is usually the easy half.": "Wir haben in den Bereichen Versicherungen, Mode, Blockchain, Immobilien, Gastgewerbe, Medizin, Wiederverkauf, E-Commerce und Bau gearbeitet. Dieser Bereich ist weniger wichtig als das, was er uns gelehrt hat: Die meisten Probleme sind nicht technischer Natur, und der technische Teil ist normalerweise der einfache Teil.",
    "We reply within 8 business hours, usually the same day. Site-down incidents on a care plan are acknowledged within two hours during business hours.": "Wir antworten innerhalb von 8 Geschäftsstunden, in der Regel noch am selben Tag. Vorfälle mit Standortausfall im Rahmen eines Pflegeplans werden innerhalb von zwei Stunden während der Geschäftszeiten bestätigt.",
    "We will tell you what we would do, what it costs, and whether you need us at all.": "Wir sagen Ihnen, was wir tun würden, was es kostet und ob Sie uns überhaupt brauchen.",
    "We will tell you what we would do, what it costs, and whether you need us at all. First reply within 8 business hours.": "Wir sagen Ihnen, was wir tun würden, was es kostet und ob Sie uns überhaupt brauchen. Erste Antwort innerhalb von 8 Geschäftsstunden.",
    "We will tell you when you do not need something": "Wir sagen Ihnen, wenn Sie etwas nicht brauchen",
    "We work with AI systems day to day, and one of us is a PhD candidate in quantum computing. That is where the name comes from: light is how you get found, and light is how quantum machines will carry information.": "Wir arbeiten täglich mit KI-Systemen und einer von uns ist Doktorand im Quantencomputing. Daher kommt auch der Name: Durch Licht wird man gefunden, und durch Licht werden Quantenmaschinen Informationen übertragen.",
    "Web applications, commerce, Shopify and BigCommerce builds": "Webanwendungen, Handel, Shopify- und BigCommerce-Builds",
    "Web platform, performance, infrastructure and networks. Your named contact on most builds.": "Webplattform, Leistung, Infrastruktur und Netzwerke. Ihr benannter Ansprechpartner für die meisten Builds.",
    "Web scraping and extraction": "Web-Scraping und -Extraktion",
    "Website visits": "Website-Besuche",
    "Websites": "Websites",
    "Websites and web apps": "Websites und Web-Apps",
    "Weinhaus · 4.0": "Weinhaus · 4.0",
    "What changes, what it improves, and what it costs to run.": "Was sich ändert, was es verbessert und was der Betrieb kostet.",
    "What do you need": "Was brauchen Sie?",
    "What happens if something breaks?": "Was passiert, wenn etwas kaputt geht?",
    "What is the quantum commitment about?": "Worum geht es bei der Quantenverpflichtung?",
    "What rent looks like in 2026": "Wie die Miete im Jahr 2026 aussieht",
    "What we do": "Was wir tun",
    "What we do, and who does it": "Was wir tun und wer es tut",
    "What we will say no to": "Wozu wir Nein sagen werden",
    "What you get is a listing that shows up when someone nearby searches for what you sell, with the right phone number, the right hours, and a route to the door. Then we keep it that way.": "Sie erhalten einen Eintrag, der angezeigt wird, wenn jemand in der Nähe nach dem sucht, was Sie verkaufen, mit der richtigen Telefonnummer, den richtigen Öffnungszeiten und einem Weg zur Tür. Dann behalten wir es bei.",
    "When quantum arrives, you move onto it for free.": "Wenn Quantum eintrifft, können Sie es kostenlos nutzen.",
    "When quantum-backed services become something we can offer in production, clients on an active care plan get their existing services migrated with no additional build fee. Running costs remain separate and are stated in advance.": "Wenn quantengestützte Dienste zu etwas werden, das wir in der Produktion anbieten können, können Kunden mit einem Active-Care-Plan ihre bestehenden Dienste ohne zusätzliche Build-Gebühr migrieren. Die laufenden Kosten bleiben gesondert und werden vorab ausgewiesen.",
    "Where the tram actually helps": "Wo die Straßenbahn tatsächlich hilft",
    "Where we are": "Wo wir sind",
    "Who owns the code and the accounts?": "Wem gehören der Code und die Konten?",
    "Why are there two price lists?": "Warum gibt es zwei Preislisten?",
