    "within 8 business hours": "innerhalb von 8 Geschäftsstunden",
    "work": "Arbeit",
    "Work": "Arbeit",
    "Work we are not the right people for. When we decline, we say who we think is a better fit.": "Arbeit, für die wir nicht die richtigen Leute sind. Wenn wir ablehnen, sagen wir, wer unserer Meinung nach besser passt.",
    "Wormeldange": "Wormeldingen",
