    "years commercial": "Jahre kommerziell",
    "Yes, 340 in Ettelbruck. Shall I reserve 50?": "Ja, 340 in Ettelbrück. Soll ich 50 reservieren?",
    "Yes. Performance work, accessibility remediation, technical SEO and migrations on sites we did not build are a normal part of what we do.": "Ja. Performance-Arbeit, Verbesserung der Barrierefreiheit, technisches SEO und Migrationen auf Websites, die wir nicht erstellt haben, sind ein normaler Teil unserer Arbeit.",
    "You are told who that is at the start, and who covers when they are away. You email them directly.": "Ihnen wird gesagt, wer das am Anfang ist und wer sie in Abwesenheit vertritt. Sie senden ihnen direkt eine E-Mail.",
    "You do. The repository is yours, the domain sits in your registrar account, and every third-party account is created in your name with you as the owner.": "Das tust du. Das Repository gehört Ihnen, die Domain befindet sich in Ihrem Registrarkonto und jedes Drittanbieterkonto wird in Ihrem Namen erstellt, wobei Sie der Eigentümer sind.",
    "You email a named person, not a ticket queue. Defects in what we agreed are fixed at no cost within the warranty window, and incident acknowledgement windows are on the commitment page.": "Sie senden eine E-Mail an eine benannte Person, nicht an eine Ticketwarteschlange. Mängel an dem, was wir vereinbart haben, werden innerhalb des Garantiefensters kostenlos behoben. Die Bestätigungsfenster für Vorfälle finden Sie auf der Verpflichtungsseite.",
    "You email a person, not a queue, and you are told who covers when they are away.": "Sie senden eine E-Mail an eine Person, nicht an eine Warteschlange, und Ihnen wird gesagt, wer für sie zuständig ist, wenn sie abwesend ist.",
    "You keep up without paying to keep up": "Sie bleiben auf dem Laufenden, ohne dafür zu bezahlen",
    "You own everything": "Dir gehört alles",
    "You own the code, the domain and every account": "Sie besitzen den Code, die Domain und jedes Konto",
