    "Hover any of the six. The same people scope, build, launch and maintain all of it.": "Zhvendosni ndonjë nga gjashtë. Të njëjtët njerëz e përpunojnë, ndërtojnë, lëshojnë dhe mirëmbajnë të gjitha.",
