    "I agree that Luminetis may store what I send in order to reply to me.": "Jam dakord që Luminetis mund të ruajë atë që dërgoj në mënyrë që të më përgjigjet.",
    "Identity, design systems, UI design, editorial content and product copy, enough design to look like a business people trust.": "Identiteti, sistemet e dizajnit, dizajni i ndërfaqes së përdoruesit, përmbajtja editoriale dhe kopja e produktit, dizajn i mjaftueshëm për t'u dukur si një biznes i besueshëm.",
    "If something goes wrong": "Nëse diçka shkon keq",
    "If we ever break one of these, tell us and we will make it right.": "Nëse e thyejmë ndonjëherë një nga këto, na trego dhe ne do ta rregullojmë.",
    "If we underestimated, that is ours to absorb. Scope changes are quoted and approved before any work starts.": "Nëse ne e nënvlerësuam, kjo është e jona për të absorbuar. Ndryshimet e fushëveprimit citohen dhe miratohen përpara se të fillojë çdo punë.",
    "If we underestimated, that is ours to absorb. Scope changes are quoted and approved in writing before any work starts.": "Nëse ne e nënvlerësuam, kjo është e jona për të absorbuar. Ndryshimet e fushëveprimit citohen dhe miratohen me shkrim përpara se të fillojë çdo punë.",
    "If your problem looks like one of these, we have solved it before.": "Nëse problemi juaj duket si një nga këto, ne e kemi zgjidhur më parë.",
    "Illustrative figures showing the shape of a first year, not a client result. We do not publish numbers we did not measure.": "Shifra ilustruese që tregojnë formën e një viti të parë, jo një rezultat klienti. Ne nuk publikojmë numra që nuk i kemi matur.",
    "In every package": "Në çdo paketë",
    "In Luxembourg and Kosovo, yes, including network and server work. Elsewhere the work is remote.": "Në Luksemburg dhe Kosovë, po, duke përfshirë punën në rrjet dhe server. Diku tjetër puna është e largët.",
    "Including when a cheaper package is the right one, and when the thing you asked for will not get you what you want.": "Përfshirë kur një paketë më e lirë është e duhura, dhe kur gjëja që keni kërkuar nuk do t'ju sjellë atë që dëshironi.",
    "Indexing, profile verification, analytics and a handover document. Accounts in your name from the start.": "Indeksimi, verifikimi i profilit, analitika dhe një dokument dorëzimi. Llogaritë në emrin tuaj që nga fillimi.",
