    "month 1": "muaji 1",
    "month 12": "muaji 12",
    "Monthly plans end with notice. Your site, code, domain and data stay yours, and we hand over anything we hold before the plan closes.": "Planet mujore përfundojnë me njoftim. Faqja juaj, kodi, domeni dhe të dhënat mbeten tuajat dhe ne dorëzojmë gjithçka që mbajmë përpara se plani të mbyllet.",
    "Monthly reconciliation runs unattended and mismatches surface the same day they happen.": "Barazimi mujor shkon pa mbikëqyrje dhe mospërputhjet shfaqen në të njëjtën ditë që ndodhin.",
    "Most of our work is under NDA, so we describe it by sector, country, scale and problem rather than by client name. Clients in Luxembourg, Kosovo, the United Kingdom and the United States. References are available on request.": "Shumica e punës sonë është nën NDA, kështu që ne e përshkruajmë atë sipas sektorit, vendit, shkallës dhe problemit dhe jo sipas emrit të klientit. Klientë në Luksemburg, Kosovë, Mbretërinë e Bashkuar dhe Shtetet e Bashkuara. Referencat janë në dispozicion sipas kërkesës.",
    "Most small businesses do not want a website. They want the phone to ring. That happens in the map result above the search results, and it only happens if the listing exists, is verified, and is complete.": "Shumica e bizneseve të vogla nuk duan një faqe interneti. Ata duan që telefoni të bjerë. Kjo ndodh në rezultatin e hartës mbi rezultatet e kërkimit dhe ndodh vetëm nëse listimi ekziston, verifikohet dhe është i plotë.",
    "Moved filtering to a pre-built facet index, deferred image decoding, and cut third-party scripts from eleven to three.": "Zhvendos filtrimin në një indeks të para-ndërtuar të aspekteve, shtyu dekodimin e imazhit dhe shkurtoi skriptet e palëve të treta nga njëmbëdhjetë në tre.",
