    "Nearer the centre is what we do most weeks. Further out is work we have done and would take again. Hover any of them.": "Më afër qendrës është ajo që bëjmë shumicën e javëve. Më tej është puna që ne kemi bërë dhe do të merrnim përsëri. Rri pezull ndonjë prej tyre.",
