    "On-site work in Luxembourg and Kosovo, remote work with the US, the UK and the rest of Europe. We shift our hours to overlap with yours.": "Punë në terren në Luksemburg dhe Kosovë, punë në distancë me SHBA, MB dhe pjesën tjetër të Evropës. Ne i zhvendosim orët tona për të mbivendosur me tuajat.",
    "One booking flow for three venues": "Një fluks rezervimi për tre vende",
    "One booking service with per-venue capacity rules, confirmation email, and a staff view that works on a phone behind the bar.": "Një shërbim rezervimi me rregullat e kapacitetit për çdo vend, email konfirmimi dhe një pamje të stafit që funksionon në një telefon pas shiritit.",
    "One build fee, then the plan that keeps you found": "Një tarifë ndërtimi, pastaj plani që ju mban të gjetur",
    "One build fee. Then the plan that keeps you found.": "Një tarifë ndërtimi. Pastaj plani që ju mban të gjetur.",
    "One conversation about what the business needs, then a written scope with a fixed price. If a cheaper package fits, we say so.": "Një bisedë për atë që i nevojitet biznesit, pastaj një fushëveprimi me shkrim me një çmim fiks. Nëse përshtatet një paketë më e lirë, ne e themi këtë.",
    "One of us is a PhD candidate in quantum computing. If quantum-backed services become production-ready, clients on an active care plan get their existing services migrated with no additional build fee. Running costs are separate and stated in advance.": "Njëri prej nesh është një kandidat për doktoraturë në informatikë kuantike. Nëse shërbimet e mbështetura nga kuantike bëhen gati për prodhim, klientët në një plan të kujdesit aktiv i transferojnë shërbimet e tyre ekzistuese pa tarifë shtesë ndërtimi. Kostot e funksionimit janë të ndara dhe të deklaruara paraprakisht.",
    "One of us is a PhD candidate in quantum computing. That is the reason this studio exists and where the name comes from. Light is how quantum machines will carry information, and it is how people find you today.": "Njëri prej nesh është një kandidat për doktoraturë në informatikë kuantike. Kjo është arsyeja pse ekziston kjo studio dhe nga vjen emri. Drita është mënyra se si makinat kuantike do të bartin informacion, dhe është mënyra se si njerëzit ju gjejnë sot.",
    "One team, start to long after launch": "Një ekip, filloni shumë kohë pas nisjes",
    "One warehouse as the source of truth, typed transforms, and a dashboard with the figures each stakeholder actually asks for.": "Një magazinë si burim i së vërtetës, transformime të shtypura dhe një tabelë me shifrat që kërkon në të vërtetë çdo palë e interesuar.",
