    "Pipelines that fail loudly rather than quietly, and AI systems that cite their source or say they do not know.": "Tubacionet që dështojnë me zë të lartë dhe jo në heshtje, dhe sistemet e AI që citojnë burimin e tyre ose thonë se nuk e dinë.",
