    "Thanks. We will reply within one business day.": "faleminderit. Ne do të përgjigjemi brenda një dite pune.",
    "The agency ranked nowhere locally and had no verified Google Business Profile for either office.": "Agjencia nuk renditej askund në nivel lokal dhe nuk kishte asnjë profil të verifikuar të biznesit të Google për asnjërën zyrë.",
    "The build fee is one-off. Care and Found are monthly and can be cancelled with notice. The build price does not change once agreed.": "Tarifa e ndërtimit është një herë. Kujdesi dhe Gjetja janë mujore dhe mund të anulohen me njoftim. Çmimi i ndërtimit nuk ndryshon pasi të jetë rënë dakord.",
    "The build is a one-off. The plan keeps the site alive and, on Found, keeps you on the map. A build requires an active Care plan; Found is optional and is what we recommend.": "Ndërtimi është një herë. Plani e mban faqen të gjallë dhe, në Found, ju mban në hartë. Një ndërtim kërkon një plan aktiv të Kujdesit; Gjetja është opsionale dhe është ajo që ne rekomandojmë.",
    "The English version of this page governs in the event of any discrepancy with a translation.": "Versioni anglisht i kësaj faqeje rregullon në rast të ndonjë mospërputhjeje me një përkthim.",
    "The Found plan": "Plani i gjetur",
    "The last vineyards on the Moselle bend": "Vreshtat e fundit në kthesën e Moselit",
    "The listing was live and complete in the first week, ahead of the site launch.": "Listimi ishte i drejtpërdrejtë dhe i plotë në javën e parë, përpara fillimit të faqes.",
    "The map result · you first, competitors grey": "Rezultati i hartës · ju së pari, konkurrentët gri",
    "The monthly pack is generated rather than assembled, and the numbers reconcile.": "Paketa mujore gjenerohet në vend që të grumbullohet dhe numrat pajtohen.",
    "The person you talk to first is the person who writes the code, and the person who answers when something breaks a year later.": "Personi me të cilin flisni i pari është personi që shkruan kodin dhe personi që përgjigjet kur diçka prishet një vit më vonë.",
    "The previous site was 6MB of sliders and did not open reliably on the clinic's own network.": "Faqja e mëparshme ishte 6 MB rrëshqitës dhe nuk hapej në mënyrë të besueshme në rrjetin e vetë klinikës.",
    "The quantum commitment": "Angazhimi kuantik",
    "The research happens on our time. You get the result as part of your existing plan.": "Hulumtimi bëhet në kohën tonë. Ju e merrni rezultatin si pjesë e planit tuaj ekzistues.",
    "The same engineers who scoped it. You see it working early and often, on a real URL, not in a slide.": "Të njëjtët inxhinierë që e trajtuan atë. Ju e shihni atë duke punuar herët dhe shpesh, në një URL të vërtetë, jo në një rrëshqitje.",
    "The same figure reads differently in Pristina and in Luxembourg City. Rather than pick one and misprice the other market, we publish both and show the list for your region. You can switch it.": "E njëjta shifër lexohet ndryshe në Prishtinë dhe në qytetin e Luksemburgut. Në vend që të zgjedhim njërën dhe t'i bëjmë çmime të gabuara tregut tjetër, ne i publikojmë të dyja dhe shfaqim listën për rajonin tuaj. Mund ta ndërroni.",
    "The same people scope, build, launch and maintain the work. There is no handoff to a junior team.": "Të njëjtët njerëz shtrijnë, ndërtojnë, nisin dhe mirëmbajnë punën. Nuk ka dorëzim për një ekip të të rinjve.",
    "The site opens in about a second on the clinic network and receptionists stopped reading the address out over the phone.": "Faqja hapet për rreth një sekondë në rrjetin e klinikës dhe recepsionistët ndaluan së lexuari adresën përmes telefonit.",
    "The team": "Ekipi",
    "The unglamorous half. If the office network drops out at eleven every morning, nothing else we build matters.": "Gjysma joglamuroze. Nëse rrjeti i zyrave del jashtë në njëmbëdhjetë çdo mëngjes, asgjë tjetër që ne ndërtojmë nuk ka rëndësi.",
    "then Care from": "pastaj Kujdesi nga",
