    "Two fields still need filling in.": "Dy fusha duhet të plotësohen ende.",
    "Two of us permanently, and a short list of senior engineers we trust when a project needs more hands. You are told who is working on your project and who to email, always.": "Dy prej nesh përgjithmonë dhe një listë e shkurtër e inxhinierëve të vjetër të cilëve u besojmë kur një projekti ka nevojë për më shumë duar. Ju thuhet se kush po punon në projektin tuaj dhe kujt t'i dërgoni email, gjithmonë.",
