    "Up to 15 pages, or a blog, or a small catalogue": "Deri në 15 faqe, ose një blog, ose një katalog të vogël",
    "Up to 5 pages, responsive, light and dark": "Deri në 5 faqe, të përgjegjshme, të lehta dhe të errëta",
    "Uptime is monitored and the office has not lost connectivity during working hours since installation.": "Koha e funksionimit monitorohet dhe zyra nuk e ka humbur lidhjen gjatë orarit të punës që nga instalimi.",
