    "VAT treatment is pending confirmation and will be stated on every quote and invoice.": "Trajtimi i TVSH-së është në pritje të konfirmimit dhe do të deklarohet në çdo kuotë dhe faturë.",
    "Verified the Google Business Profile first, completed hours, photos and categories, then built a five-page site around it.": "Verifiko fillimisht profilin e biznesit të Google, përfundoi orët, fotot dhe kategoritë, më pas ndërtoi një sajt me pesë faqe rreth tij.",
    "VINERA": "VINERA",
    "Vinera, your business": "Vinera, biznesi juaj",
    "Warehousing": "Magazinimi",
    "Washer, DIN 125": "Rondele, DIN 125",
    "Watch it happen, screen by screen.": "Shikoni të ndodhë, ekran për ekran.",
    "We are based in Luxembourg and Kosovo, and we work with clients in the United States, the United Kingdom and across Europe. Time zones have never been the problem: we move our hours to overlap with yours, early or late, and we say up front which hours you will get us in.": "Ne jemi të vendosur në Luksemburg dhe Kosovë, dhe punojmë me klientë në Shtetet e Bashkuara, Mbretërinë e Bashkuar dhe në mbarë Evropën. Zonat kohore nuk kanë qenë kurrë problemi: ne i lëvizim orët tona që të mbivendosen me tuajat, herët ose vonë, dhe themi përpara se në cilat orë do të na futni.",
    "We have worked in insurance, fashion, blockchain, real estate, hospitality, medicine, reselling, e-commerce and construction. That range matters less than what it taught us: most problems are not technical, and the technical part is usually the easy half.": "Ne kemi punuar në sigurime, modë, blockchain, pasuri të paluajtshme, mikpritje, mjekësi, rishitje, tregti elektronike dhe ndërtim. Kjo gamë ka më pak rëndësi se sa na mësoi: shumica e problemeve nuk janë teknike dhe pjesa teknike zakonisht është gjysma e lehtë.",
    "We reply within 8 business hours, usually the same day. Site-down incidents on a care plan are acknowledged within two hours during business hours.": "Ne përgjigjemi brenda 8 orëve të punës, zakonisht në të njëjtën ditë. Incidentet e uljes në terren në një plan kujdesi pranohen brenda dy orëve gjatë orarit të punës.",
    "We will tell you what we would do, what it costs, and whether you need us at all.": "Ne do t'ju tregojmë se çfarë do të bënim, sa kushton dhe nëse keni nevojë për ne fare.",
    "We will tell you what we would do, what it costs, and whether you need us at all. First reply within 8 business hours.": "Ne do t'ju tregojmë se çfarë do të bënim, sa kushton dhe nëse keni nevojë për ne fare. Përgjigja e parë brenda 8 orëve të punës.",
    "We will tell you when you do not need something": "Ne do t'ju tregojmë kur nuk keni nevojë për diçka",
    "We work with AI systems day to day, and one of us is a PhD candidate in quantum computing. That is where the name comes from: light is how you get found, and light is how quantum machines will carry information.": "Ne punojmë me sistemet e AI ditë pas dite dhe njëri prej nesh është kandidat për doktoraturë në informatikë kuantike. Nga vjen emri: drita është mënyra se si gjen dhe drita është mënyra se si makinat kuantike do të bartin informacion.",
    "Web applications, commerce, Shopify and BigCommerce builds": "Aplikacionet në internet, tregtia, Shopify dhe ndërtimet BigCommerce",
    "Web platform, performance, infrastructure and networks. Your named contact on most builds.": "Ueb platforma, performanca, infrastruktura dhe rrjetet. Kontakti juaj i emërtuar në shumicën e ndërtimeve.",
    "Web scraping and extraction": "Skrapimi dhe nxjerrja e uebit",
