    "Weinhaus · 4.0": "Weinhaus · 4.0",
    "What changes, what it improves, and what it costs to run.": "Çfarë ndryshon, çfarë përmirëson dhe sa kushton të ekzekutohet.",
    "What do you need": "Çfarë ju duhet",
    "What happens if something breaks?": "Çfarë ndodh nëse diçka prishet?",
    "What is the quantum commitment about?": "Për çfarë është angazhimi kuantik?",
    "What rent looks like in 2026": "Si duket qiraja në vitin 2026",
    "What we do": "Çfarë bëjmë ne",
    "What we do, and who does it": "Çfarë bëjmë ne dhe kush e bën atë",
    "What we will say no to": "Çfarë do t'i themi jo",
    "What you get is a listing that shows up when someone nearby searches for what you sell, with the right phone number, the right hours, and a route to the door. Then we keep it that way.": "Ajo që ju merrni është një listë që shfaqet kur dikush në afërsi kërkon për atë që ju shisni, me numrin e duhur të telefonit, orët e duhura dhe një rrugë drejt derës. Pastaj e mbajmë në atë mënyrë.",
    "When quantum arrives, you move onto it for free.": "Kur arrin kuanti, ju kaloni në të falas.",
    "When quantum-backed services become something we can offer in production, clients on an active care plan get their existing services migrated with no additional build fee. Running costs remain separate and are stated in advance.": "Kur shërbimet e mbështetura nga kuantike bëhen diçka që ne mund ta ofrojmë në prodhim, klientët në një plan të kujdesit aktiv i migrojnë shërbimet e tyre ekzistuese pa tarifë shtesë ndërtimi. Kostot e funksionimit mbeten të ndara dhe deklarohen paraprakisht.",
    "Where the tram actually helps": "Aty ku tramvaji në të vërtetë ndihmon",
    "Where we are": "Ku jemi",
    "Who owns the code and the accounts?": "Kush e zotëron kodin dhe llogaritë?",
    "Why are there two price lists?": "Pse ka dy lista çmimesh?",
