    "Work": "Puna",
    "Work we are not the right people for. When we decline, we say who we think is a better fit.": "Puna për të cilën ne nuk jemi njerëzit e duhur. Kur refuzojmë, themi se kush mendojmë se është më i përshtatshëm.",
    "Wormeldange": "Wormeldange",
