    "years commercial": "vite komerciale",
    "Yes, 340 in Ettelbruck. Shall I reserve 50?": "Po, 340 në Ettelbruck. A duhet të rezervoj 50?",
    "Yes. Performance work, accessibility remediation, technical SEO and migrations on sites we did not build are a normal part of what we do.": "po. Puna e performancës, korrigjimi i aksesueshmërisë, SEO teknike dhe migrimet në faqet që ne nuk kemi ndërtuar janë një pjesë normale e asaj që bëjmë.",
    "You are told who that is at the start, and who covers when they are away. You email them directly.": "Ju thuhet se kush është në fillim dhe kush mbulon kur janë larg. Ju i dërgoni email direkt.",
    "You do. The repository is yours, the domain sits in your registrar account, and every third-party account is created in your name with you as the owner.": "Ju bëni. Depoja është e juaja, domeni ndodhet në llogarinë tuaj të regjistruesit dhe çdo llogari e palës së tretë krijohet në emrin tuaj me ju si pronar.",
    "You email a named person, not a ticket queue. Defects in what we agreed are fixed at no cost within the warranty window, and incident acknowledgement windows are on the commitment page.": "Ju dërgoni email një personi të emërtuar, jo një radhë biletash. Defektet në atë që kemi rënë dakord rregullohen pa kosto brenda dritares së garancisë dhe dritaret e njohjes së incidentit janë në faqen e angazhimit.",
    "You email a person, not a queue, and you are told who covers when they are away.": "Ju dërgoni email një personi, jo një radhë, dhe ju thuhet se kush mbulon kur ai është larg.",
    "You keep up without paying to keep up": "Ju vazhdoni pa paguar për të vazhduar",
    "You own everything": "Ju zotëroni gjithçka",
