    "Luminetis home": "casa luminetis",
    "Luminetis is a small studio of senior engineers, with people in Luxembourg and Kosovo. Today that is two senior software engineers with a combined decade-plus of commercial experience, including work with UK-based companies. When a project needs more, we bring in senior people we have worked with before: software, data and AI engineers at the same level, never a junior team learning on your budget.": "Luminetis es un pequeño estudio de ingenieros superiores, con gente en Luxemburgo y Kosovo. Hoy son dos ingenieros de software senior con más de una década de experiencia comercial combinada, incluido el trabajo con empresas con sede en el Reino Unido. Cuando un proyecto necesita más, incorporamos a personas de alto nivel con las que hemos trabajado antes: ingenieros de software, datos e inteligencia artificial del mismo nivel, nunca un equipo junior que aprende con su presupuesto.",
