    "Marketing sites, custom builds, Shopify and BigCommerce, headless commerce, migrations without losing URLs, and performance work on sites we did not build.": "Sitios de marketing, compilaciones personalizadas, Shopify y BigCommerce, comercio sin cabeza, migraciones sin perder URL y trabajo de rendimiento en sitios que no creamos.",
