    "month 12": "mes 12",
    "Monthly plans end with notice. Your site, code, domain and data stay yours, and we hand over anything we hold before the plan closes.": "Los planes mensuales finalizan con aviso. Su sitio, código, dominio y datos siguen siendo suyos y le entregamos todo lo que tenemos antes de que se cierre el plan.",
    "Monthly reconciliation runs unattended and mismatches surface the same day they happen.": "La conciliación mensual se realiza sin supervisión y los desajustes surgen el mismo día en que ocurren.",
    "Most of our work is under NDA, so we describe it by sector, country, scale and problem rather than by client name. Clients in Luxembourg, Kosovo, the United Kingdom and the United States. References are available on request.": "La mayor parte de nuestro trabajo se realiza bajo NDA, por lo que lo describimos por sector, país, escala y problema en lugar de por nombre del cliente. Clientes en Luxemburgo, Kosovo, Reino Unido y Estados Unidos. Las referencias están disponibles bajo petición.",
    "Most small businesses do not want a website. They want the phone to ring. That happens in the map result above the search results, and it only happens if the listing exists, is verified, and is complete.": "La mayoría de las pequeñas empresas no quieren un sitio web. Quieren que suene el teléfono. Esto sucede en el resultado del mapa encima de los resultados de la búsqueda y solo sucede si el listado existe, está verificado y está completo.",
    "Moved filtering to a pre-built facet index, deferred image decoding, and cut third-party scripts from eleven to three.": "Se movió el filtrado a un índice de facetas prediseñado, se difirió la decodificación de imágenes y se redujeron los scripts de terceros de once a tres.",
    "ms": "señora",
    "name": "nombre",
    "Name": "Nombre",
    "Native and cross-platform apps, internal tools, dashboards, integrations and API design, usually where a spreadsheet stopped being enough.": "Aplicaciones nativas y multiplataforma, herramientas internas, paneles, integraciones y diseño de API, donde normalmente una hoja de cálculo dejó de ser suficiente.",
    "Native mobile apps": "Aplicaciones móviles nativas",
    "natural wine luxembourg": "vino natural luxemburgo",
    "Nearer the centre is what we do most weeks. Further out is work we have done and would take again. Hover any of them.": "Más cerca del centro es lo que hacemos la mayoría de las semanas. Más adelante está el trabajo que hemos hecho y que volveríamos a realizar. Coloca el cursor sobre cualquiera de ellos.",
