    "Not a complete list, and not the limit. If your problem is not on it, ask. We will tell you plainly whether it is ours to take or someone else&apos;s.": "No es una lista completa, ni el límite. Si tu problema no está en eso, pregunta. Le diremos claramente si es nuestro o de otra persona.",
