    "On-site network work": "Trabajo en red in situ",
    "On-site work in Luxembourg and Kosovo, remote work with the US, the UK and the rest of Europe. We shift our hours to overlap with yours.": "Trabajo presencial en Luxemburgo y Kosovo, trabajo remoto con EE.UU., Reino Unido y el resto de Europa. Cambiamos nuestro horario para superponernos al suyo.",
    "One booking flow for three venues": "Un flujo de reservas para tres lugares",
    "One booking service with per-venue capacity rules, confirmation email, and a staff view that works on a phone behind the bar.": "Un servicio de reserva con reglas de capacidad por lugar, correo electrónico de confirmación y una vista del personal que funciona en un teléfono detrás de la barra.",
    "One build fee, then the plan that keeps you found": "Una tarifa de construcción y luego el plan que te mantiene encontrado",
    "One build fee. Then the plan that keeps you found.": "Una tarifa de construcción. Entonces encontrarás el plan que te mantiene.",
    "One conversation about what the business needs, then a written scope with a fixed price. If a cheaper package fits, we say so.": "Una conversación sobre lo que necesita la empresa y luego un alcance escrito con un precio fijo. Si encaja un paquete más económico, lo decimos.",
    "One of us is a PhD candidate in quantum computing. If quantum-backed services become production-ready, clients on an active care plan get their existing services migrated with no additional build fee. Running costs are separate and stated in advance.": "Uno de nosotros es candidato a doctorado en computación cuántica. Si los servicios con respaldo cuántico están listos para producción, los clientes con un plan de atención activo migrarán sus servicios existentes sin tarifa de construcción adicional. Los costos de funcionamiento son separados y se declaran por adelantado.",
    "One of us is a PhD candidate in quantum computing. That is the reason this studio exists and where the name comes from. Light is how quantum machines will carry information, and it is how people find you today.": "Uno de nosotros es candidato a doctorado en computación cuántica. Por eso existe este estudio y de ahí viene el nombre. La luz es la forma en que las máquinas cuánticas transportarán información, y así es como la gente te encuentra hoy.",
    "One team, start to long after launch": "Un equipo, comienza mucho después del lanzamiento.",
    "One warehouse as the source of truth, typed transforms, and a dashboard with the figures each stakeholder actually asks for.": "Un almacén como fuente de verdad, transformaciones escritas y un panel con las cifras que cada parte interesada realmente solicita.",
