    "Pipelines that fail loudly, warehousing, reporting, extraction, retrieval systems and agents that cite their source or say they do not know.": "Oleoductos que fallan estrepitosamente, sistemas de almacenamiento, informes, extracción y recuperación y agentes que citan su fuente o dicen no saberlo.",
