    "Supplier price lists arrived as HTML pages and PDFs, and every layout change silently broke the import.": "Las listas de precios de proveedores llegaban como páginas HTML y PDF, y cada cambio de diseño interrumpía silenciosamente la importación.",
    "Switches, routers, firewalls": "Conmutadores, enrutadores, cortafuegos",
