    "Tap-to-call from the listing, before anyone opens the site.": "Toque para llamar desde la lista, antes de que alguien abra el sitio.",
    "Technical SEO audits and remediation": "Auditorías técnicas de SEO y remediación",
    "Technical SEO foundations, sitemap, structured data": "Fundamentos técnicos de SEO, mapa del sitio, datos estructurados.",
    "Technical work first, because content ranks only if the site can be crawled and read quickly. Then the writing.": "Primero el trabajo técnico, porque el contenido sólo se clasifica si el sitio se puede rastrear y leer rápidamente. Luego la escritura.",
