    "Tell us what you sell and where you are.": "Cuéntanos qué vendes y dónde estás.",
    "Ten years of commercial work. Some of it we had to go back through invoices to remember.": "Diez años de labor comercial. Parte de ello tuvimos que revisar las facturas para recordarlo.",
    "Ten years, mapped": "Diez años, mapeados",
    "Terms of service": "Términos de servicio",
    "text": "texto",
    "Thanks. We will reply within one business day.": "Gracias. Le responderemos dentro de un día hábil.",
    "The agency ranked nowhere locally and had no verified Google Business Profile for either office.": "La agencia no obtuvo ninguna clasificación a nivel local y no tenía un perfil comercial de Google verificado para ninguna de las oficinas.",
    "The build fee is one-off. Care and Found are monthly and can be cancelled with notice. The build price does not change once agreed.": "La tarifa de construcción es única. Care and Found son mensuales y se pueden cancelar con previo aviso. El precio de construcción no cambia una vez acordado.",
    "The build is a one-off. The plan keeps the site alive and, on Found, keeps you on the map. A build requires an active Care plan; Found is optional and is what we recommend.": "La construcción es única. El plan mantiene vivo el sitio y, en Found, lo mantiene en el mapa. Una construcción requiere un plan de atención activo; Found es opcional y es lo que recomendamos.",
    "The English version of this page governs in the event of any discrepancy with a translation.": "La versión en inglés de esta página rige en caso de cualquier discrepancia con una traducción.",
    "The Found plan": "El plan encontrado",
    "The last vineyards on the Moselle bend": "Los últimos viñedos en la curva del Mosela",
    "The listing was live and complete in the first week, ahead of the site launch.": "El listado estuvo activo y completo en la primera semana, antes del lanzamiento del sitio.",
    "The map result · you first, competitors grey": "El resultado del mapa · tú primero, los competidores en gris",
    "The monthly pack is generated rather than assembled, and the numbers reconcile.": "El paquete mensual se genera en lugar de ensamblarse y las cifras se concilian.",
    "The person you talk to first is the person who writes the code, and the person who answers when something breaks a year later.": "La persona con la que hablas primero es la persona que escribe el código y la persona que responde cuando algo falla un año después.",
    "The previous site was 6MB of sliders and did not open reliably on the clinic's own network.": "El sitio anterior tenía 6 MB de controles deslizantes y no se abría de manera confiable en la propia red de la clínica.",
    "The quantum commitment": "El compromiso cuántico",
    "The research happens on our time. You get the result as part of your existing plan.": "La investigación ocurre en nuestro tiempo. Obtiene el resultado como parte de su plan existente.",
    "The same engineers who scoped it. You see it working early and often, on a real URL, not in a slide.": "Los mismos ingenieros que lo examinaron. Lo verás funcionando desde el principio y con frecuencia, en una URL real, no en una diapositiva.",
    "The same figure reads differently in Pristina and in Luxembourg City. Rather than pick one and misprice the other market, we publish both and show the list for your region. You can switch it.": "La misma cifra se lee de manera diferente en Pristina y en la ciudad de Luxemburgo. En lugar de elegir uno y valorar mal el otro mercado, publicamos ambos y mostramos la lista para su región. Puedes cambiarlo.",
    "The same people scope, build, launch and maintain the work. There is no handoff to a junior team.": "Las mismas personas analizan, construyen, lanzan y mantienen el trabajo. No hay traspaso a un equipo junior.",
    "The site opens in about a second on the clinic network and receptionists stopped reading the address out over the phone.": "El sitio se abre en aproximadamente un segundo en la red de la clínica y los recepcionistas dejaron de leer la dirección por teléfono.",
    "The team": "el equipo",
    "The unglamorous half. If the office network drops out at eleven every morning, nothing else we build matters.": "La mitad poco glamorosa. Si la red de la oficina se corta a las once de la mañana, nada más que construyamos importa.",
