    "Two of us permanently, and a short list of senior engineers we trust when a project needs more hands. You are told who is working on your project and who to email, always.": "Dos de nosotros permanentemente y una breve lista de ingenieros senior en los que confiamos cuando un proyecto necesita más manos. Siempre se le indica quién está trabajando en su proyecto y a quién enviar un correo electrónico.",
    "two offices, nine agents": "dos oficinas, nueve agentes",
