    "Luminetis is a small studio of senior engineers, with people in Luxembourg and Kosovo. Today that is two senior software engineers with a combined decade-plus of commercial experience, including work with UK-based companies. When a project needs more, we bring in senior people we have worked with before: software, data and AI engineers at the same level, never a junior team learning on your budget.": "Luminetis é um pequeno estúdio de engenheiros seniores, com pessoas no Luxemburgo e no Kosovo. Hoje são dois engenheiros de software seniores com mais de uma década de experiência comercial combinada, incluindo trabalho com empresas sediadas no Reino Unido. Quando um projeto precisa de mais, contratamos pessoas seniores com quem já trabalhamos: engenheiros de software, dados e IA do mesmo nível, nunca uma equipe júnior aprendendo dentro do seu orçamento.",
