    "Monthly plans end with notice. Your site, code, domain and data stay yours, and we hand over anything we hold before the plan closes.": "Os planos mensais terminam com aviso prévio. Seu site, código, domínio e dados permanecem seus, e nós entregamos tudo o que possuímos antes do encerramento do plano.",
    "Monthly reconciliation runs unattended and mismatches surface the same day they happen.": "A reconciliação mensal ocorre sem supervisão e as incompatibilidades surgem no mesmo dia em que ocorrem.",
    "Most of our work is under NDA, so we describe it by sector, country, scale and problem rather than by client name. Clients in Luxembourg, Kosovo, the United Kingdom and the United States. References are available on request.": "A maior parte do nosso trabalho está sob NDA, por isso o descrevemos por setor, país, escala e problema, e não pelo nome do cliente. Clientes no Luxemburgo, Kosovo, Reino Unido e Estados Unidos. Referências estão disponíveis mediante solicitação.",
    "Most small businesses do not want a website. They want the phone to ring. That happens in the map result above the search results, and it only happens if the listing exists, is verified, and is complete.": "A maioria das pequenas empresas não quer um site. Eles querem que o telefone toque. Isso acontece no resultado do mapa acima dos resultados da pesquisa e só acontece se a listagem existir, for verificada e completa.",
    "Moved filtering to a pre-built facet index, deferred image decoding, and cut third-party scripts from eleven to three.": "Filtragem movida para um índice de faceta pré-construído, decodificação de imagem adiada e corte de scripts de terceiros de onze para três.",
