    "On-site work in Luxembourg and Kosovo, remote work with the US, the UK and the rest of Europe. We shift our hours to overlap with yours.": "Trabalho presencial no Luxemburgo e no Kosovo, trabalho remoto com os EUA, o Reino Unido e o resto da Europa. Mudamos nosso horário para coincidir com o seu.",
    "One booking flow for three venues": "Um fluxo de reserva para três locais",
    "One booking service with per-venue capacity rules, confirmation email, and a staff view that works on a phone behind the bar.": "Um serviço de reserva com regras de capacidade por local, e-mail de confirmação e visualização da equipe que funciona em um telefone atrás do bar.",
    "One build fee, then the plan that keeps you found": "Uma taxa de construção e depois o plano que mantém você encontrado",
    "One build fee. Then the plan that keeps you found.": "Uma taxa de construção. Então o plano que mantém você encontrado.",
    "One conversation about what the business needs, then a written scope with a fixed price. If a cheaper package fits, we say so.": "Uma conversa sobre o que a empresa precisa e, em seguida, um escopo escrito com preço fixo. Se couber um pacote mais barato, nós o avisamos.",
    "One of us is a PhD candidate in quantum computing. If quantum-backed services become production-ready, clients on an active care plan get their existing services migrated with no additional build fee. Running costs are separate and stated in advance.": "Um de nós é doutorando em computação quântica. Se os serviços apoiados por quantum estiverem prontos para produção, os clientes em um plano de assistência ativa terão seus serviços existentes migrados sem nenhuma taxa adicional de construção. Os custos de funcionamento são separados e declarados antecipadamente.",
    "One of us is a PhD candidate in quantum computing. That is the reason this studio exists and where the name comes from. Light is how quantum machines will carry information, and it is how people find you today.": "Um de nós é doutorando em computação quântica. É por isso que este estúdio existe e de onde vem o nome. A luz é como as máquinas quânticas transportarão informações e é como as pessoas encontram você hoje.",
    "One team, start to long after launch": "Uma equipe, começa muito depois do lançamento",
