    "text": "texto",
    "Thanks. We will reply within one business day.": "Obrigado. Responderemos dentro de um dia útil.",
    "The agency ranked nowhere locally and had no verified Google Business Profile for either office.": "A agência não estava classificada em nenhum lugar localmente e não tinha perfil comercial do Google verificado para nenhum dos escritórios.",
    "The build fee is one-off. Care and Found are monthly and can be cancelled with notice. The build price does not change once agreed.": "A taxa de construção é única. Care and Found são mensais e podem ser cancelados mediante aviso prévio. O preço de construção não muda uma vez acordado.",
    "The build is a one-off. The plan keeps the site alive and, on Found, keeps you on the map. A build requires an active Care plan; Found is optional and is what we recommend.": "A construção é única. O plano mantém o site vivo e, no Found, mantém você no mapa. Uma construção requer um plano de cuidados ativo; Encontrado é opcional e é o que recomendamos.",
    "The English version of this page governs in the event of any discrepancy with a translation.": "A versão em inglês desta página prevalecerá no caso de qualquer discrepância com a tradução.",
    "The Found plan": "O plano encontrado",
    "The last vineyards on the Moselle bend": "Os últimos vinhedos na curva do Mosela",
    "The listing was live and complete in the first week, ahead of the site launch.": "A listagem foi publicada e completa na primeira semana, antes do lançamento do site.",
    "The map result · you first, competitors grey": "O resultado do mapa · você primeiro, concorrentes cinza",
    "The monthly pack is generated rather than assembled, and the numbers reconcile.": "O pacote mensal é gerado em vez de montado, e os números se reconciliam.",
    "The person you talk to first is the person who writes the code, and the person who answers when something breaks a year later.": "A pessoa com quem você fala primeiro é a pessoa que escreve o código e a pessoa que responde quando algo quebra um ano depois.",
    "The previous site was 6MB of sliders and did not open reliably on the clinic's own network.": "O site anterior tinha 6 MB de controles deslizantes e não abria de forma confiável na própria rede da clínica.",
    "The quantum commitment": "O compromisso quântico",
    "The research happens on our time. You get the result as part of your existing plan.": "A pesquisa acontece no nosso tempo. Você obtém o resultado como parte de seu plano existente.",
    "The same engineers who scoped it. You see it working early and often, on a real URL, not in a slide.": "Os mesmos engenheiros que fizeram o escopo. Você vê isso funcionando cedo e com frequência, em uma URL real, não em um slide.",
    "The same figure reads differently in Pristina and in Luxembourg City. Rather than pick one and misprice the other market, we publish both and show the list for your region. You can switch it.": "O mesmo número tem uma leitura diferente em Pristina e na cidade do Luxemburgo. Em vez de escolher um e avaliar mal o outro mercado, publicamos ambos e mostramos a lista para sua região. Você pode trocá-lo.",
    "The same people scope, build, launch and maintain the work. There is no handoff to a junior team.": "As mesmas pessoas definem o escopo, constroem, lançam e mantêm o trabalho. Não há transferência para uma equipe júnior.",
    "The site opens in about a second on the clinic network and receptionists stopped reading the address out over the phone.": "O site abre em cerca de um segundo na rede da clínica e as recepcionistas pararam de ler o endereço pelo telefone.",
    "The team": "A equipe",
    "The unglamorous half. If the office network drops out at eleven every morning, nothing else we build matters.": "A metade sem glamour. Se a rede do escritório cair às onze da manhã, nada mais que construirmos terá importância.",
