    "Two of us permanently, and a short list of senior engineers we trust when a project needs more hands. You are told who is working on your project and who to email, always.": "Dois de nós permanentemente e uma pequena lista de engenheiros seniores em quem confiamos quando um projeto precisa de mais mãos. Você é informado sobre quem está trabalhando em seu projeto e para quem enviar e-mail, sempre.",
