    "Up to 15 pages, or a blog, or a small catalogue": "Até 15 páginas, ou um blog, ou um pequeno catálogo",
    "Up to 5 pages, responsive, light and dark": "Até 5 páginas, responsivo, claro e escuro",
    "Uptime is monitored and the office has not lost connectivity during working hours since installation.": "O tempo de atividade é monitorado e o escritório não perdeu conectividade durante o horário comercial desde a instalação.",
