    "VAT treatment is pending confirmation and will be stated on every quote and invoice.": "O tratamento do IVA está pendente de confirmação e será indicado em cada orçamento e fatura.",
    "Verified the Google Business Profile first, completed hours, photos and categories, then built a five-page site around it.": "Verifiquei primeiro o perfil da empresa no Google, completei horários, fotos e categorias e, em seguida, criei um site de cinco páginas em torno dele.",
    "VINERA": "VINERA",
    "Vinera, your business": "Vinera, seu negócio",
    "Warehousing": "Armazenagem",
    "Washer, DIN 125": "Arruela, DIN 125",
    "Watch it happen, screen by screen.": "Veja isso acontecer, tela por tela.",
    "We are based in Luxembourg and Kosovo, and we work with clients in the United States, the United Kingdom and across Europe. Time zones have never been the problem: we move our hours to overlap with yours, early or late, and we say up front which hours you will get us in.": "Estamos sediados no Luxemburgo e no Kosovo e trabalhamos com clientes nos Estados Unidos, no Reino Unido e em toda a Europa. Os fusos horários nunca foram o problema: mudamos nossos horários para coincidir com os seus, mais cedo ou mais tarde, e dizemos antecipadamente em que horas você nos receberá.",
    "We have worked in insurance, fashion, blockchain, real estate, hospitality, medicine, reselling, e-commerce and construction. That range matters less than what it taught us: most problems are not technical, and the technical part is usually the easy half.": "Atuamos em seguros, moda, blockchain, imobiliário, hotelaria, medicina, revenda, e-commerce e construção. Essa faixa importa menos do que aquilo que nos ensinou: a maioria dos problemas não são técnicos, e a parte técnica geralmente é a metade fácil.",
    "We reply within 8 business hours, usually the same day. Site-down incidents on a care plan are acknowledged within two hours during business hours.": "Respondemos em até 8 horas úteis, geralmente no mesmo dia. Os incidentes de local inativo em um plano de cuidados são reconhecidos dentro de duas horas durante o horário comercial.",
    "We will tell you what we would do, what it costs, and whether you need us at all.": "Diremos a você o que faríamos, quanto custa e se você precisa de nós.",
    "We will tell you what we would do, what it costs, and whether you need us at all. First reply within 8 business hours.": "Diremos a você o que faríamos, quanto custa e se você precisa de nós. Primeira resposta em até 8 horas úteis.",
    "We will tell you when you do not need something": "Nós lhe diremos quando você não precisar de algo",
    "We work with AI systems day to day, and one of us is a PhD candidate in quantum computing. That is where the name comes from: light is how you get found, and light is how quantum machines will carry information.": "Trabalhamos com sistemas de IA no dia a dia e um de nós é doutorando em computação quântica. É daí que vem o nome: a luz é como você é encontrado e a luz é como as máquinas quânticas transportam informações.",
    "Web applications, commerce, Shopify and BigCommerce builds": "Aplicações web, comércio, Shopify e BigCommerce",
    "Web platform, performance, infrastructure and networks. Your named contact on most builds.": "Plataforma web, desempenho, infraestrutura e redes. Seu contato nomeado na maioria das versões.",
    "Web scraping and extraction": "Web scraping e extração",
    "Website visits": "Visitas ao site",
    "Websites": "Sites",
