    "Weinhaus · 4.0": "Weinhaus · 4.0",
    "What changes, what it improves, and what it costs to run.": "O que muda, o que melhora e quanto custa para funcionar.",
    "What do you need": "O que você precisa",
    "What happens if something breaks?": "O que acontece se algo quebrar?",
    "What is the quantum commitment about?": "Sobre o que é o compromisso quântico?",
    "What rent looks like in 2026": "Como será o aluguel em 2026",
    "What we do": "O que fazemos",
    "What we do, and who does it": "O que fazemos e quem faz",
    "What we will say no to": "Ao que diremos não",
    "What you get is a listing that shows up when someone nearby searches for what you sell, with the right phone number, the right hours, and a route to the door. Then we keep it that way.": "O que você obtém é uma listagem que aparece quando alguém próximo pesquisa o que você vende, com o número de telefone certo, o horário certo e o caminho até a porta. Então mantemos assim.",
    "When quantum arrives, you move onto it for free.": "Quando o quantum chega, você passa para ele de graça.",
    "When quantum-backed services become something we can offer in production, clients on an active care plan get their existing services migrated with no additional build fee. Running costs remain separate and are stated in advance.": "Quando os serviços apoiados por quantum se tornam algo que podemos oferecer na produção, os clientes com um plano de cuidados ativos migram seus serviços existentes sem nenhuma taxa adicional de construção. Os custos de funcionamento permanecem separados e são declarados antecipadamente.",
    "Where the tram actually helps": "Onde o bonde realmente ajuda",
    "Where we are": "Onde estamos",
    "Who owns the code and the accounts?": "Quem é o dono do código e das contas?",
