    "Yes, 340 in Ettelbruck. Shall I reserve 50?": "Sim, 340 em Ettelbruck. Devo reservar 50?",
    "Yes. Performance work, accessibility remediation, technical SEO and migrations on sites we did not build are a normal part of what we do.": "Sim. Trabalho de desempenho, correção de acessibilidade, SEO técnico e migrações em sites que não construímos são parte normal do que fazemos.",
    "You are told who that is at the start, and who covers when they are away. You email them directly.": "Você é informado de quem é no início e quem cobre quando eles estão ausentes. Você envia um e-mail diretamente para eles.",
    "You do. The repository is yours, the domain sits in your registrar account, and every third-party account is created in your name with you as the owner.": "Você faz. O repositório é seu, o domínio fica na sua conta de registrador e todas as contas de terceiros são criadas em seu nome, sendo você o proprietário.",
    "You email a named person, not a ticket queue. Defects in what we agreed are fixed at no cost within the warranty window, and incident acknowledgement windows are on the commitment page.": "Você envia um e-mail para uma pessoa nomeada, não para uma fila de tickets. Os defeitos no que combinamos são corrigidos sem nenhum custo dentro do período de garantia, e as janelas de confirmação de incidentes estão na página de compromisso.",
    "You email a person, not a queue, and you are told who covers when they are away.": "Você envia um e-mail para uma pessoa, não para uma fila, e é informado sobre quem cobre quando ela está ausente.",
