    "If we underestimated, that is ours to absorb. Scope changes are quoted and approved before any work starts.": "Se lo sottovalutiamo, spetta a noi assorbirlo. Le modifiche all'ambito vengono preventivate e approvate prima dell'inizio di qualsiasi lavoro.",
    "If we underestimated, that is ours to absorb. Scope changes are quoted and approved in writing before any work starts.": "Se lo sottovalutiamo, spetta a noi assorbirlo. Le modifiche all'ambito vengono citate e approvate per iscritto prima dell'inizio di qualsiasi lavoro.",
    "If your problem looks like one of these, we have solved it before.": "Se il tuo problema assomiglia a uno di questi, lo abbiamo già risolto.",
    "Illustrative figures showing the shape of a first year, not a client result. We do not publish numbers we did not measure.": "Figure illustrative che mostrano la forma di un primo anno, non il risultato del cliente. Non pubblichiamo numeri che non abbiamo misurato.",
    "In every package": "In ogni confezione",
    "In Luxembourg and Kosovo, yes, including network and server work. Elsewhere the work is remote.": "In Lussemburgo e Kosovo sì, compreso il lavoro sulla rete e sui server. Altrove il lavoro è remoto.",
