    "Luminetis home": "Casa Lumineti",
    "Luminetis is a small studio of senior engineers, with people in Luxembourg and Kosovo. Today that is two senior software engineers with a combined decade-plus of commercial experience, including work with UK-based companies. When a project needs more, we bring in senior people we have worked with before: software, data and AI engineers at the same level, never a junior team learning on your budget.": "Luminetis è un piccolo studio di ingegneri senior, con persone in Lussemburgo e Kosovo. Oggi si tratta di due ingegneri software senior con oltre dieci anni di esperienza commerciale combinata, compreso il lavoro con aziende con sede nel Regno Unito. Quando un progetto richiede di più, coinvolgiamo persone senior con cui abbiamo lavorato in precedenza: ingegneri di software, dati e intelligenza artificiale allo stesso livello, mai un team junior che apprende con il tuo budget.",
