    "Native and cross-platform apps, internal tools, dashboards, integrations and API design, usually where a spreadsheet stopped being enough.": "App native e multipiattaforma, strumenti interni, dashboard, integrazioni e progettazione API, solitamente dove un foglio di calcolo non è più sufficiente.",
