    "Nearer the centre is what we do most weeks. Further out is work we have done and would take again. Hover any of them.": "Più vicino al centro è ciò che facciamo la maggior parte delle settimane. Più lontano c'è il lavoro che abbiamo svolto e che riprenderemmo. Passa il mouse su uno di essi.",
