    "One booking flow for three venues": "Un flusso di prenotazione per tre sedi",
    "One booking service with per-venue capacity rules, confirmation email, and a staff view that works on a phone behind the bar.": "Un servizio di prenotazione con regole di capacità per sede, e-mail di conferma e visualizzazione del personale che funziona su un telefono dietro il bancone.",
    "One build fee, then the plan that keeps you found": "Una tariffa di costruzione, poi il piano che ti mantiene trovato",
