    "text": "testo",
    "Thanks. We will reply within one business day.": "Grazie. Risponderemo entro un giorno lavorativo.",
    "The agency ranked nowhere locally and had no verified Google Business Profile for either office.": "L'agenzia non si classificava da nessuna parte a livello locale e non aveva un profilo dell'attività Google verificato per nessuno dei due uffici.",
    "The build fee is one-off. Care and Found are monthly and can be cancelled with notice. The build price does not change once agreed.": "Il costo di costruzione è una tantum. Care e Found hanno cadenza mensile e possono essere cancellati con preavviso. Il prezzo di costruzione non cambia una volta concordato.",
    "The build is a one-off. The plan keeps the site alive and, on Found, keeps you on the map. A build requires an active Care plan; Found is optional and is what we recommend.": "La costruzione è una tantum. Il piano mantiene vivo il sito e, su Found, ti mantiene sulla mappa. Una build richiede un piano di assistenza attivo; Trovato è facoltativo ed è ciò che consigliamo.",
    "The English version of this page governs in the event of any discrepancy with a translation.": "In caso di discrepanze con la traduzione prevale la versione inglese di questa pagina.",
    "The Found plan": "Il piano Trovato",
    "The last vineyards on the Moselle bend": "Gli ultimi vigneti sull'ansa della Mosella",
    "The listing was live and complete in the first week, ahead of the site launch.": "L'elenco è stato pubblicato e completato nella prima settimana, prima del lancio del sito.",
    "The map result · you first, competitors grey": "Il risultato della mappa · tu per primo, i concorrenti sono grigi",
    "The monthly pack is generated rather than assembled, and the numbers reconcile.": "Il pacchetto mensile viene generato anziché assemblato e i numeri si riconciliano.",
    "The person you talk to first is the person who writes the code, and the person who answers when something breaks a year later.": "La persona con cui parli per prima è la persona che scrive il codice e la persona che risponde quando qualcosa si rompe un anno dopo.",
    "The previous site was 6MB of sliders and did not open reliably on the clinic's own network.": "Il sito precedente conteneva 6 MB di slider e non si apriva in modo affidabile sulla rete della clinica.",
    "The quantum commitment": "L'impegno quantistico",
    "The research happens on our time. You get the result as part of your existing plan.": "La ricerca avviene nel nostro tempo. Ottieni il risultato come parte del tuo piano esistente.",
    "The same engineers who scoped it. You see it working early and often, on a real URL, not in a slide.": "Gli stessi ingegneri che l'hanno analizzato. Lo vedi funzionare presto e spesso, su un URL reale, non in una diapositiva.",
    "The same figure reads differently in Pristina and in Luxembourg City. Rather than pick one and misprice the other market, we publish both and show the list for your region. You can switch it.": "La stessa cifra si legge in modo diverso a Pristina e nella città di Lussemburgo. Invece di sceglierne uno e valutare erroneamente l'altro mercato, li pubblichiamo entrambi e mostriamo l'elenco per la tua regione. Puoi cambiarlo.",
    "The same people scope, build, launch and maintain the work. There is no handoff to a junior team.": "Le stesse persone individuano, costruiscono, lanciano e mantengono il lavoro. Non è previsto il passaggio a una squadra junior.",
    "The site opens in about a second on the clinic network and receptionists stopped reading the address out over the phone.": "Il sito si apre in circa un secondo sulla rete della clinica e gli addetti alla reception hanno smesso di leggere l'indirizzo al telefono.",
    "The team": "La squadra",
    "The unglamorous half. If the office network drops out at eleven every morning, nothing else we build matters.": "La metà poco affascinante. Se la rete dell'ufficio si interrompe ogni mattina alle undici, nient'altro che costruiamo ha importanza.",
