    "Two of us permanently, and a short list of senior engineers we trust when a project needs more hands. You are told who is working on your project and who to email, always.": "Due di noi in modo permanente e un breve elenco di ingegneri senior di cui ci fidiamo quando un progetto richiede più mani. Ti viene detto chi sta lavorando al tuo progetto e a chi inviare un'e-mail, sempre.",
