    "VAT treatment is pending confirmation and will be stated on every quote and invoice.": "Il trattamento IVA è in attesa di conferma e sarà indicato su ogni preventivo e fattura.",
    "Verified the Google Business Profile first, completed hours, photos and categories, then built a five-page site around it.": "Innanzitutto ho verificato il profilo dell'attività su Google, ho completato orari, foto e categorie, quindi ho creato attorno ad esso un sito di cinque pagine.",
    "VINERA": "VINERA",
    "Vinera, your business": "Vinera, affari tuoi",
    "Warehousing": "Magazzinaggio",
    "Washer, DIN 125": "Rondella, DIN 125",
    "Watch it happen, screen by screen.": "Guardalo accadere, schermata dopo schermata.",
    "We are based in Luxembourg and Kosovo, and we work with clients in the United States, the United Kingdom and across Europe. Time zones have never been the problem: we move our hours to overlap with yours, early or late, and we say up front which hours you will get us in.": "Abbiamo sede in Lussemburgo e Kosovo e lavoriamo con clienti negli Stati Uniti, nel Regno Unito e in tutta Europa. I fusi orari non sono mai stati un problema: spostiamo i nostri orari in modo che si sovrappongano ai tuoi, in anticipo o in ritardo, e diciamo in anticipo in quali orari ci farai entrare.",
    "We have worked in insurance, fashion, blockchain, real estate, hospitality, medicine, reselling, e-commerce and construction. That range matters less than what it taught us: most problems are not technical, and the technical part is usually the easy half.": "Abbiamo lavorato nel settore assicurativo, moda, blockchain, immobiliare, ospitalità, medicina, rivendita, e-commerce ed edilizia. Quella portata conta meno di quello che ci ha insegnato: la maggior parte dei problemi non sono tecnici, e la parte tecnica è solitamente la metà facile.",
    "We reply within 8 business hours, usually the same day. Site-down incidents on a care plan are acknowledged within two hours during business hours.": "Rispondiamo entro 8 ore lavorative, solitamente lo stesso giorno. Gli incidenti di inattività su un piano di assistenza vengono riconosciuti entro due ore durante l'orario lavorativo.",
    "We will tell you what we would do, what it costs, and whether you need us at all.": "Ti diremo cosa faremmo, quanto costerebbe e se hai bisogno di noi.",
    "We will tell you what we would do, what it costs, and whether you need us at all. First reply within 8 business hours.": "Ti diremo cosa faremmo, quanto costerebbe e se hai bisogno di noi. Prima risposta entro 8 ore lavorative.",
    "We will tell you when you do not need something": "Ti diremo quando non avrai bisogno di qualcosa",
    "We work with AI systems day to day, and one of us is a PhD candidate in quantum computing. That is where the name comes from: light is how you get found, and light is how quantum machines will carry information.": "Lavoriamo quotidianamente con i sistemi di intelligenza artificiale e uno di noi è un dottorando in informatica quantistica. Da qui il nome: la luce è il modo in cui vieni trovato, e la luce è il modo in cui le macchine quantistiche trasporteranno le informazioni.",
    "Web applications, commerce, Shopify and BigCommerce builds": "Applicazioni Web, commercio, build Shopify e BigCommerce",
    "Web platform, performance, infrastructure and networks. Your named contact on most builds.": "Piattaforma web, prestazioni, infrastrutture e reti. Il tuo contatto nominato sulla maggior parte delle build.",
